async function _getBenchmarkData({ tagIds = [], transaction = null, allowGlobalFallback = false } = {}) {
  const allTags = await listAllPulseTags({ transaction });
  const requestedTags = allTags.filter((tag) => tagIds.includes(tag.id));

  const combosToScores = await getCombosToScores({ transaction });

  const requestedTagTypeMap = {};
  requestedTags.forEach((tag) => {
    requestedTagTypeMap[tag.type] = tag.id;
  });

  const tagIdToTag = {};
  allTags.forEach((tag) => {
    tagIdToTag[tag.id] = tag;
  });

  const requestedTagCombos = getCombos(requestedTagTypeMap);

  const requestedTagComboToScoreCount = {};
  requestedTagCombos.forEach((combo) => {
    requestedTagComboToScoreCount[combo] = combosToScores?.[combo]?.length;
  });

  // Find the combos with >=10 scores. Choose the smallest combo (least scores) with best match (most tags).
  // The smallest combo is likely the group of pulses that have the most in common with the requested tags.
  let smallestCombo;
  let smallestComboCount = Infinity;
  let bestMatchedTags = 0;

  const smallestComboCountPerNumTags = { bestMatchedTags: smallestComboCount };
  Object.entries(requestedTagComboToScoreCount).forEach(([combo, count]) => {
    const numMatchedTags = combo === 'global' ? 0 : combo?.split('_').length;

    // To make a benchmark, you must have at least enough scores to calculate a quartile.
    const enoughScores = hasCompleteBenchmarkPopulation(combosToScores?.[combo]);
    const enoughTags = numMatchedTags >= bestMatchedTags;
    const notInScoreNumTagsObj = !smallestComboCountPerNumTags?.[numMatchedTags];
    const beatsScoreNumTagsObj = count < smallestComboCountPerNumTags?.[numMatchedTags] ?? Infinity;
    const qualifiedForScoreNumTagsObj = notInScoreNumTagsObj || beatsScoreNumTagsObj;

    if (enoughScores && enoughTags && qualifiedForScoreNumTagsObj) {
      smallestCombo = combo;
      smallestComboCount = count;
      bestMatchedTags = numMatchedTags;
      smallestComboCountPerNumTags[numMatchedTags] = count;
    }
  });

  // Return the scores associated with the smallest combo.
  if (tagIds.length > 0 && !allowGlobalFallback && (!smallestCombo || smallestCombo === 'global')) {
    return { tags: requestedTags, diagnosticToBenchmarkData: {} };
  }

  const scores = combosToScores?.[smallestCombo];

  const tags = [];
  if (smallestCombo !== 'global') {
    const comboTagIds = smallestCombo?.split('_') ?? [];
    tags.push(...comboTagIds.map((tagId) => tagIdToTag[tagId]));
  }

  const diagnosticToBenchmarkData = {};
  (scores ?? []).forEach((score) => {
    const createdAt = score.createdAt;
    // horrible hack to port scores generated using the same model, but with a different cosmetic scaling applied
    if (shouldRescaleScore({ createdAt })) {
      const transformedDiagnosticScores = Object.entries(score.scores)
        .filter(([scoreName]) => {
          return BOXCOX_TRANFORM_PARAMS?.[scoreName];
        })
        .map(([scoreName, scoreObj]) => {
          const boxcoxParams = BOXCOX_TRANFORM_PARAMS[scoreName];
          const boxcoxValue = boxcox(scoreObj.score, boxcoxParams.lambda);
          const rescaled = rescaleToRange(
            boxcoxValue,
            boxcoxParams.min,
            boxcoxParams.max,
            PULSE_SCORE_DISPLAY_MIN,
            PULSE_SCORE_DISPLAY_MAX
          );
          const rounded = roundToNearestIncrement(rescaled, ROUND_INCREMENT);

          const clamped = Math.min(PULSE_SCORE_DISPLAY_MAX, Math.max(PULSE_SCORE_DISPLAY_MIN, rounded));
          return { scoreName, ...scoreObj, score: clamped };
        });

      const topLevelScore = roundToNearestIncrement(
        mean(
          transformedDiagnosticScores.map((scoreRecord) => {
            return scoreRecord.score;
          })
        ),
        ROUND_INCREMENT
      );

      if (!diagnosticToBenchmarkData?.topLevel) {
        diagnosticToBenchmarkData.topLevel = [];
      }

      diagnosticToBenchmarkData.topLevel.push(topLevelScore);

      transformedDiagnosticScores.forEach((scoreRecord) => {
        const { scoreName, score } = scoreRecord;

        if (!diagnosticToBenchmarkData[scoreName]) {
          diagnosticToBenchmarkData[scoreName] = [];
        }

        diagnosticToBenchmarkData[scoreName].push(score);
      });
    } else {
      Object.entries(score.scores).forEach(([scoreName, scoreObj]) => {
        if (!diagnosticToBenchmarkData[scoreName]) {
          diagnosticToBenchmarkData[scoreName] = [];
        }

        diagnosticToBenchmarkData[scoreName].push(scoreObj.score);
      });
    }
  });

  return { tags, diagnosticToBenchmarkData };
}

function _calculateBenchmark(sampleScores, pulseScore) {
  const sampleMean = mean(sampleScores);
  const sampleMedian = median(sampleScores);
  const sampleStdev = std(sampleScores);
  const percentile = _calculatePercentile(sampleScores, pulseScore);
  const n = sampleScores.length;

  return { mean: sampleMean, median: sampleMedian, stdev: sampleStdev, percentile, n };
}

function _calculatePercentile(numbers, value) {
  const sortedNumbers = numbers.sort((a, b) => a - b);
  const rank = sortedNumbers.findIndex((num) => num >= value);
  if (rank === -1) {
    return 100;
  }
  return (rank / sortedNumbers.length) * 100;
}

async function getSanitizedBenchmarks({ sessionResultId }, { transaction = null } = {}) {
  const benchmark = await models.PulseBenchmark.findOne({
    where: { sessionResultId, isActive: true, deletedAt: null },
    order: [['createdAt', SortDirection.Descending]],
    transaction,
  });

  if (!benchmark) return {};

  const sanitizedBenchmarks = { benchmarks: {} };

  Object.entries(benchmark.scores).forEach(([diagnostic, scoreData]) => {
    const { score, percentile } = scoreData;
    const details = benchmark.details[diagnostic];
    const numPulses = details.n;
    let percentileType;
    if (numPulses >= PulsePercentileThreshold[PulsePercentileType.Quartile]) {
      percentileType = PulsePercentileType.Quartile;
    }
    const percentileString = _getPercentile(percentile, percentileType);
    const roundedScore = Math.round(score);

    sanitizedBenchmarks.benchmarks[diagnostic] = { score: roundedScore, percentile: percentileString };

    // Scope, percentile type, and scope are the same for all diagnostics.
    sanitizedBenchmarks.tags = details?.tags ?? [];
    sanitizedBenchmarks.scope = details?.tags?.length > 0 ? 'tags' : 'global';
    sanitizedBenchmarks.percentileType = percentileType;
  });

  return sanitizedBenchmarks;
}

function _getPercentile(percentile, percentileType) {
  // If your percentile is actually zero (scale goes from 0 to 100), then you belong in the bottom quartile.
  // However, because the math relies on rounding up, ceil(0 * anything) is still 0, so you don't get assigned 25/10.
  // So if the percentile is 0, make it slightly higher so it gets correctly rounded up.
  let percentileForCalculation = percentile;
  if (percentile === 0) percentileForCalculation = 0.01;
  if (percentileType === PulsePercentileType.Quartile) {
    // Round to nearest quartile.
    const quartile = Math.ceil(percentileForCalculation / 25) * 25;
    return PulseBenchmarkQuartile[quartile];
  }
  return null;
}

