/**
 * Creates search string combos to look for similar pulses.
 *
 * Strings are created by concatenating the tag ids together with underscores. Up to one of each tag type is allowed.
 * The order is always product, industry, asset.
 *
 * Valid combos:
 * - product
 * - industry
 * - asset
 * - product_industry
 * - product_asset
 * - industry_asset
 * - product_industry_asset
 *
 * 'global' is the default combo.
 *
 * @param {Object} tagTypeToId Map of tag type to the ids of tags of that type
 * @returns Array<String> Possible combos
 */
function getCombos(tagTypeToId) {
  const productTagId = tagTypeToId?.[PulseTagType.Product];
  const industryTagId = tagTypeToId?.[PulseTagType.Industry];
  const assetTagId = tagTypeToId?.[PulseTagType.Asset];

  // All pulses contribute to the global combo.
  const possibleCombos = ['global'];

  if (productTagId) {
    possibleCombos.push(productTagId);
  }

  if (industryTagId) {
    possibleCombos.push(industryTagId);
  }

  if (assetTagId) {
    possibleCombos.push(assetTagId);
  }

  if (productTagId && industryTagId) {
    possibleCombos.push(`${productTagId}_${industryTagId}`);
  }

  if (productTagId && assetTagId) {
    possibleCombos.push(`${productTagId}_${assetTagId}`);
  }

  if (industryTagId && assetTagId) {
    possibleCombos.push(`${industryTagId}_${assetTagId}`);
  }

  if (productTagId && industryTagId && assetTagId) {
    possibleCombos.push(`${productTagId}_${industryTagId}_${assetTagId}`);
  }

  return possibleCombos;
}

